import { asset, img, prefersReducedMotion } from './dom';
import manifest from './sprite-manifest.json';

const TILE = 64;
const ROLE: Record<string, [number, number]> = {
  tl: [0, 0], t: [1, 0], tr: [2, 0], l: [0, 1], c: [1, 1], r: [2, 1], bl: [0, 2], b: [1, 2], br: [2, 2],
};

export type Terrain = 'spring' | 'meadow' | 'autumn' | 'dusk';
/** Every sprite that can be placed in a world (generated by scripts/build_assets.py). */
export type SpriteName = keyof typeof manifest;
type SheetInfo = { w: number; h: number; frames: number; fps: number };
const SHEETS = manifest as Record<SpriteName, SheetInfo>;

/** Celebration animation of each character that has one. */
const CHEER: Partial<Record<SpriteName, SpriteName>> = {
  'units/pawn-blue': 'units/pawn-blue-run',
  'units/warrior-blue': 'units/warrior-blue-attack',
  'units/archer-blue': 'units/archer-blue-shoot',
  'units/monk-blue': 'units/monk-blue-heal',
  'units/monk-purple': 'units/monk-purple-heal',
  'units/sheep': 'units/sheep-move',
  'units/sheep-grazing': 'units/sheep-move',
};

export interface PutOptions {
  scale?: number;
  flip?: boolean;
  /** Raised above everything at its depth (e.g. archers standing on a tower). */
  above?: boolean;
  /** Placed but invisible until `appear`. */
  hidden?: boolean;
  dim?: boolean;
}

export type Sprite = HTMLDivElement;

/**
 * A pixel-art diorama: water, islands built tile by tile and animated sprites anchored by their feet.
 * Scene operations (appear, vanish, swap, move, fx) run animated, or instantly when `instant` is set
 * (redraws, reduced motion). Purely decorative, so it is hidden from assistive technology.
 */
export class World {
  readonly el: HTMLDivElement;
  /** When true, scene operations apply their end state immediately, without effects. */
  instant = prefersReducedMotion();
  private timers: number[] = [];

  constructor(className = '') {
    this.el = document.createElement('div');
    this.el.className = `world ${className}`.trim();
    this.el.setAttribute('aria-hidden', 'true');
  }

  /** Flat island of cols x rows tiles with its top-left corner at (x, y), and animated foam around it. */
  island(x: number, y: number, cols: number, rows: number, terrain: Terrain, dim = false): void {
    const frag = document.createDocumentFragment();
    const tiles: HTMLElement[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const role = (r === 0 ? 't' : r === rows - 1 ? 'b' : '') + (c === 0 ? 'l' : c === cols - 1 ? 'r' : '') || 'c';
        const [tx, ty] = ROLE[role] ?? ROLE.c!;
        if (role !== 'c') {
          const foam = document.createElement('div');
          foam.className = 'foam';
          foam.style.left = `${x + c * TILE - TILE}px`;
          foam.style.top = `${y + r * TILE - TILE}px`;
          foam.style.animationDelay = `${-((r * 7 + c * 3) % 16) / 10}s`;
          frag.prepend(foam);
        }
        const tile = document.createElement('div');
        tile.className = dim ? 'tile dim' : 'tile';
        tile.style.left = `${x + c * TILE}px`;
        tile.style.top = `${y + r * TILE}px`;
        tile.style.backgroundImage = `url("${asset(`terrain/island-${terrain}.png`)}")`;
        tile.style.backgroundPosition = `${-tx * TILE}px ${-ty * TILE}px`;
        tiles.push(tile);
      }
    }
    frag.append(...tiles);
    this.el.append(frag);
  }

  /** Places a sprite so that its feet (bottom centre) sit at (x, y). Depth follows y. */
  put(name: SpriteName, x: number, y: number, opts: PutOptions = {}): Sprite {
    const el = document.createElement('div');
    el.className = 'sprite';
    el.dataset.idle = name;
    const k = opts.scale ?? 1;
    el.style.left = `${Math.round(x)}px`;
    el.style.top = `${Math.round(y)}px`;
    el.style.setProperty('--sx', String(opts.flip ? -k : k));
    el.style.setProperty('--sy', String(k));
    el.style.zIndex = String((opts.above ? 2000 : 100) + Math.round(y));
    if (opts.dim) el.classList.add('dim');
    if (opts.hidden) el.classList.add('is-hidden');
    setSheet(el, name);
    // Random phase so a crowd does not move in lockstep.
    el.style.animationDelay = `${-Math.random() * 2}s`;
    this.el.append(el);
    return el;
  }

  cloud(n: 1 | 2 | 3 | 5, x: number, y: number, scale = 1): void {
    const c = img(`props/cloud-${n}.png`, 'cloud');
    c.style.left = `${x}px`;
    c.style.top = `${y}px`;
    c.style.width = `${Math.round(576 * scale)}px`;
    this.el.append(c);
  }

  // ---------- scene operations ----------

  private later(delay: number, fn: () => void): void {
    if (this.instant || delay <= 0) fn();
    else this.timers.push(window.setTimeout(fn, delay));
  }

  /** One-shot effect (dust, explosion, fire burst…) centred at the feet position, removed when it ends. */
  fx(name: SpriteName, x: number, y: number, delay = 0, scale = 1): void {
    if (this.instant) return;
    this.later(delay, () => {
      const el = this.put(name, x, y, { scale, above: true });
      el.style.animationDelay = '0s';
      el.style.animationIterationCount = '1';
      el.addEventListener('animationend', () => el.remove(), { once: true });
    });
  }

  private puff(el: Sprite, delay: number): void {
    const k = Number(el.style.getPropertyValue('--sy')) || 1;
    this.fx('fx/dust', parseFloat(el.style.left), parseFloat(el.style.top) + 4, delay, k * 1.2);
  }

  appear(el: Sprite | null, delay = 0): void {
    if (!el) return;
    this.later(delay, () => {
      if (!this.instant) this.puff(el, 0);
      el.classList.remove('is-hidden');
    });
  }

  vanish(el: Sprite | null, delay = 0): void {
    if (!el) return;
    this.later(delay, () => {
      if (this.instant) return el.remove();
      this.puff(el, 0);
      el.classList.add('is-hidden');
      this.timers.push(window.setTimeout(() => el.remove(), 400));
    });
  }

  /** Changes what a sprite is (e.g. a ruin becoming a house), with a puff of dust. */
  swap(el: Sprite | null, name: SpriteName, delay = 0, dust = true): void {
    if (!el) return;
    this.later(delay, () => {
      if (dust && !this.instant) this.puff(el, 0);
      el.dataset.idle = name;
      setSheet(el, name);
    });
  }

  /** Walks a sprite to (x, y), optionally playing `run` on the way and becoming `end` on arrival. */
  move(el: Sprite | null, x: number, y: number, opts: { ms?: number; delay?: number; run?: SpriteName; end?: SpriteName } = {}): void {
    if (!el) return;
    const finish = () => {
      el.style.transition = '';
      el.style.left = `${Math.round(x)}px`;
      el.style.top = `${Math.round(y)}px`;
      el.style.zIndex = String(100 + Math.round(y));
      const end = opts.end ?? (el.dataset.idle as SpriteName);
      el.dataset.idle = end;
      setSheet(el, end);
    };
    if (this.instant) return finish();
    this.later(opts.delay ?? 0, () => {
      const from = parseFloat(el.style.left);
      const k = Math.abs(Number(el.style.getPropertyValue('--sx')) || 1);
      el.style.setProperty('--sx', String(x < from ? -k : k));
      if (opts.run) setSheet(el, opts.run);
      const ms = opts.ms ?? 900;
      el.style.transition = `left ${ms}ms linear, top ${ms}ms linear`;
      el.style.left = `${Math.round(x)}px`;
      el.style.top = `${Math.round(y)}px`;
      this.timers.push(window.setTimeout(finish, ms));
    });
  }

  /** Every character with a celebration plays it twice with a little hop, then goes back to idle. */
  celebrate(): void {
    if (this.instant) return;
    this.el.querySelectorAll<Sprite>('.sprite:not(.is-hidden)').forEach((el, i) => {
      const cheer = CHEER[el.dataset.idle as SpriteName];
      if (!cheer) return;
      this.later(150 + (i % 5) * 110, () => {
        setSheet(el, cheer);
        el.style.animationDelay = '0s';
        el.animate([{ translate: '0 0' }, { translate: '0 -14px' }, { translate: '0 0' }], { duration: 480, iterations: 2, easing: 'steps(4)' });
        this.timers.push(window.setTimeout(() => setSheet(el, el.dataset.idle as SpriteName), 1400));
      });
    });
  }

  clear(): void {
    this.destroy();
    this.el.replaceChildren();
  }

  /** Cancels pending scene operations (the screen is going away). */
  destroy(): void {
    this.timers.forEach((t) => clearTimeout(t));
    this.timers = [];
  }
}

/** Shows a sprite strip on an element: size, image and frame animation. */
function setSheet(el: Sprite, name: SpriteName): void {
  const s = SHEETS[name];
  el.style.width = `${s.w}px`;
  el.style.height = `${s.h}px`;
  el.style.backgroundImage = `url("${asset(`${name}.png`)}")`;
  el.style.backgroundSize = `${s.w * s.frames}px ${s.h}px`;
  el.style.backgroundPositionX = '0px';
  el.classList.toggle('anim', s.frames > 1);
  el.style.setProperty('--frames', String(s.frames));
  el.style.setProperty('--sheet-w', `${s.w * s.frames}px`);
  el.style.setProperty('--dur', `${(s.frames / s.fps).toFixed(2)}s`);
}

/** True when a sprite name exists (used by tests on scene definitions). */
export function isSprite(name: string): name is SpriteName {
  return name in SHEETS;
}
